108. //==================================================================================================
109. // Traits and Types
110. //==================================================================================================
111. 
112. ///
113. /// # Description
114. ///
115. /// Aligns `value` up to the next multiple of `alignment`.
116. ///
117. /// # Parameters
118. ///
119. /// - `value`: Value to align.
120. /// - `alignment`: Alignment boundary.
121. ///
122. /// # Returns
123. ///
124. /// Returns the aligned value, or `None` if `alignment` is zero or the computation overflows.
125. ///
126. pub const fn align_up(value: usize, alignment: usize) -> Option<usize> {
127.     if alignment == 0 {
128.         return None;
129.     }
130.     value.div_ceil(alignment).checked_mul(alignment)
131. }
132. 
133. ///
134. /// # Description
135. ///
136. /// Error type returned by [`FixedSizeBumpAllocator`] operations.
137. ///
138. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
139. pub enum BumpAllocError {
140.     /// Storage capacity exhausted.
141.     Exhausted,
142.     /// Type size does not match allocator unit size.
143.     SizeMismatch,
144.     /// Type alignment exceeds allocator alignment.
145.     AlignmentMismatch,
146.     /// Internal arithmetic overflow.
147.     Overflow,
148.     /// Computed slot exceeds storage bounds.
149.     OutOfBounds,
150.     /// Computed slot is not properly aligned.
151.     Misaligned,
152. }
153. 
154. impl fmt::Display for BumpAllocError {
155.     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
156.         match self {
157.             Self::Exhausted => write!(f, "fixed-size BSS allocator exhausted"),
158.             Self::SizeMismatch => write!(f, "type size does not match allocator unit size"),
159.             Self::AlignmentMismatch => write!(f, "type alignment exceeds allocator alignment"),
160.             Self::Overflow => write!(f, "allocator internal arithmetic overflow"),
161.             Self::OutOfBounds => write!(f, "allocator slot exceeds storage bounds"),
162.             Self::Misaligned => write!(f, "allocator returned misaligned slot"),
163.         }
164.     }
165. }
166. 
167. ///
168. /// # Description
169. ///
170. /// Backend trait for fixed-size allocators that draw memory from static storage.
171. ///
172. /// # Safety
173. ///
174. /// Implementers must guarantee that:
175. ///
176. /// - `as_mut_ptr()` returns a stable pointer to a backing region of at least `STORAGE_SIZE`
177. ///   bytes for the allocator lifetime.
178. /// - the backing region is writable and properly aligned for any allocation site that uses this
179. ///   backend.
180. /// - the backing region is exclusively managed by this allocator API, so creating `&'static mut`
181. ///   references from slots cannot alias with other mutable references.
182. ///
183. pub unsafe trait BssStorage {
184.     /// Number of fixed-size units that can be allocated.
185.     const NUM_UNITS: usize;
186. 
187.     /// Total size in bytes of the backing storage region.
188.     const STORAGE_SIZE: usize;
189. 
190.     /// Returns a mutable pointer to the beginning of the storage region.
191.     fn as_mut_ptr() -> *mut u8;
192. }
193. 
194. ///
195. /// # Description
196. ///
197. /// Generic fixed-size bump allocator over statically reserved memory.
198. ///
199. /// # Type Parameters
200. ///
201. /// - `N`: Unit size in bytes.
202. /// - `A`: Unit alignment in bytes.
203. /// - `S`: Backing storage provider.
204. ///
205. pub struct FixedSizeBumpAllocator<const N: usize, const A: usize, S: BssStorage> {
206.     /// Atomic bump index for the next available slot.
207.     next_slot: AtomicUsize,
208.     /// Marker for the backend storage provider.
209.     _storage: PhantomData<S>,
210. }
211. 
212. impl<const N: usize, const A: usize, S: BssStorage> FixedSizeBumpAllocator<N, A, S> {
213.     ///
214.     /// # Description
215.     ///
216.     /// Creates a new fixed-size bump allocator.
217.     ///
218.     /// # Returns
219.     ///
220.     /// Returns a new allocator.
221.     ///
222.     /// # Safety
223.     ///
224.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
225.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
226.     /// backend causes independent bump counters, which leads to overlapping slot reservations
227.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
228.     ///
229.     pub const unsafe fn new() -> Self {
230.         Self {
231.             next_slot: AtomicUsize::new(0),
232.             _storage: PhantomData,
233.         }
234.     }
235. 
236.     ///
237.     /// # Description
238.     ///
239.     /// Allocates the next fixed-size slot as a raw byte array.
240.     ///
241.     /// # Returns
242.     ///
243.     /// On success, returns a mutable reference to a unit-sized byte array.
244.     ///
245.     /// # Errors
246.     ///
247.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
248.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
249.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
250.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
251.     ///
252.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
253.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
254.         let idx: usize = loop {
255.             let current: usize = self.next_slot.load(Ordering::Acquire);
256.             if current >= S::NUM_UNITS {
257.                 return Err(BumpAllocError::Exhausted);
258.             }
259.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
260.             if self
261.                 .next_slot
262.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
263.                 .is_ok()
264.             {
265.                 break current;
266.             }
267.         };
268. 
269.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
270.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
271. 
272.         let base: usize = S::as_mut_ptr() as usize;
273.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
274.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
275.         let storage_end: usize = base
276.             .checked_add(S::STORAGE_SIZE)
277.             .ok_or(BumpAllocError::Overflow)?;
278.         if end > storage_end {
279.             return Err(BumpAllocError::OutOfBounds);
280.         }
281.         if !ptr.is_multiple_of(A) {
282.             return Err(BumpAllocError::Misaligned);
283.         }
284. 
285.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
286.         // out at most once by atomic compare-and-swap.
287.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
288.     }
289. 
290.     ///
291.     /// # Description
292.     ///
293.     /// Allocates the next fixed-size slot and reinterprets it as `MaybeUninit<T>`.
294.     ///
295.     /// # Returns
296.     ///
297.     /// On success, returns a mutable reference to an uninitialized `T`.
298.     ///
299.     /// # Errors
300.     ///
301.     /// - [`BumpAllocError::SizeMismatch`] if `size_of::<T>() != N`.
302.     /// - [`BumpAllocError::AlignmentMismatch`] if `align_of::<T>() > A`.
303.     /// - Any error from [`alloc()`](Self::alloc).
304.     ///
305.     /// # Safety
306.     ///
307.     /// The caller must initialise the returned `MaybeUninit<T>` before reading through it
308.     /// and ensure exclusive use of the returned reference.
309.     ///
310.     pub unsafe fn alloc_as<T>(&self) -> Result<&'static mut MaybeUninit<T>, BumpAllocError> {
311.         if core::mem::size_of::<T>() != N {
312.             return Err(BumpAllocError::SizeMismatch);
313.         }
314.         if core::mem::align_of::<T>() > A {
315.             return Err(BumpAllocError::AlignmentMismatch);
316.         }
317. 
318.         let slot: &'static mut [u8; N] = self.alloc()?;
319.         // SAFETY: size/alignment checks above guarantee this cast is valid.
320.         Ok(unsafe { &mut *(slot.as_mut_ptr() as *mut MaybeUninit<T>) })
321.     }
322. }
323. 
324. impl<const N: usize, const A: usize, S: BssStorage> Default for FixedSizeBumpAllocator<N, A, S> {
325.     fn default() -> Self {
326.         // SAFETY: caller is responsible for the singleton invariant.
327.         unsafe { Self::new() }
328.     }
329. }
330. 
