10. //==================================================================================================
11. // BitmapView - Abstract Specification Model
12. //==================================================================================================
13. 
14. /// A view of the Bitmap as a set of indices where bits are set.
15. #[verifier::ext_equal]
16. pub struct BitmapView {
17.     /// Number of bits in the bitmap.
18.     pub num_bits: int,
19.     /// Set of indices where bits are set (0-indexed).
20.     /// Invariant: all elements are in [0, num_bits).
21.     pub set_bits: Set<int>,
22. }
23. 
24. impl BitmapView {
25.     /// Returns the usage (count of set bits) in the bitmap view.
26.     /// Requires set_bits to be finite (enforced by Bitmap::inv()).
27.     pub open spec fn usage(&self) -> int {
28.         self.set_bits.len() as int
29.     }
30. 
31.     /// Returns true if there exists at least one unset bit.
32.     pub open spec fn has_free_bit(&self) -> bool {
33.         exists|i: int| 0 <= i < self.num_bits && !self.set_bits.contains(i)
34.     }
35. 
36.     /// Returns true if the bitmap is full (all bits set).
37.     pub open spec fn is_full(&self) -> bool {
38.         forall|i: int| 0 <= i < self.num_bits ==> self.set_bits.contains(i)
39.     }
40. 
41.     /// Returns true if the bitmap is empty (no bits set).
42.     pub open spec fn is_empty(&self) -> bool {
43.         self.set_bits == Set::<int>::empty()
44.     }
45. 
46.     /// Returns true if a specific bit is set.
47.     pub open spec fn is_bit_set(&self, index: int) -> bool {
48.         self.set_bits.contains(index)
49.     }
50. 
51.     /// Helper: Create a set of indices in range [start, end).
52.     pub open spec fn range_set(start: int, end: int) -> Set<int> {
53.         Set::new(|i: int| start <= i < end)
54.     }
55. 
56.     /// Well-formedness: set_bits only contains valid indices.
57.     pub open spec fn wf(&self) -> bool {
58.         forall|i: int| self.set_bits.contains(i) ==> 0 <= i < self.num_bits
59.     }
60. 
61.     /// Helper spec function: check if all bits in range [start, end) are set.
62.     pub open spec fn all_bits_set_in_range(&self, start: int, end: int) -> bool {
63.         forall|i: int| start <= i < end ==> self.is_bit_set(i)
64.     }
65. 
66.     /// Helper spec function: check if all bits in range [start, end) are not set.
67.     pub open spec fn all_bits_unset_in_range(&self, start: int, end: int) -> bool {
68.         forall|i: int| start <= i < end ==> !self.is_bit_set(i)
69.     }
70. 
71.     /// Helper spec function: check if there exists a contiguous range of n free bits starting at start.
72.     pub open spec fn has_free_range_at(&self, start: int, n: int) -> bool {
73.         &&& 0 <= start
74.         &&& start + n <= self.num_bits
75.         &&& self.all_bits_unset_in_range(start, start + n)
76.     }
77. 
78.     /// Helper spec function: check if there exists a contiguous range of n free bits.
79.     pub open spec fn exists_contiguous_free_range(&self, n: int) -> bool {
80.         exists|start: int|
81.             #![trigger self.has_free_range_at(start, n)]
82.             self.has_free_range_at(start, n)
83.     }
84. 
85.     /// A subset of a finite set is finite.
86.     pub proof fn lemma_set_bits_finite(&self)
87.         requires
88.             self.wf(),
89.             self.num_bits >= 0,
90.         ensures
91.             self.set_bits.finite(),
92.     {
93.         let full_range: Set<int> = vstd::set_lib::set_int_range(0, self.num_bits);
94.         vstd::set_lib::lemma_int_range(0, self.num_bits);
95. 
96.         assert(self.set_bits.subset_of(full_range)) by {
97.             assert forall|i: int| #![auto] self.set_bits.contains(i) implies full_range.contains(
98.                 i,
99.             ) by {}
100.         }
101. 
102.         vstd::set_lib::lemma_set_subset_finite(full_range, self.set_bits);
103.     }
104. 
105.     //==================================================================================================
106.     // Lemmas: Finiteness
107.     //==================================================================================================
108. 
109.     /// range_set(lo, hi) is finite when lo <= hi.
110.     pub proof fn lemma_range_set_finite(lo: int, hi: int)
111.         requires
112.             lo <= hi,
113.         ensures
114.             BitmapView::range_set(lo, hi).finite(),
115.     {
116.         vstd::set_lib::lemma_int_range(lo, hi);
117.         assert(BitmapView::range_set(lo, hi) =~= vstd::set_lib::set_int_range(lo, hi)) by {
118.             assert forall|i: int|
119.                 BitmapView::range_set(lo, hi).contains(i) == vstd::set_lib::set_int_range(
120.                     lo,
121.                     hi,
122.                 ).contains(i) by {}
123.         }
124.     }
125. 
126.     //==================================================================================================
127.     // Lemmas: Cardinality
128.     //==================================================================================================
129. 
130.     /// range_set cardinality equals range size.
131.     pub proof fn lemma_range_set_len(lo: int, hi: int)
132.         requires
133.             lo <= hi,
134.         ensures
135.             BitmapView::range_set(lo, hi).len() == hi - lo,
136.     {
137.         vstd::set_lib::lemma_int_range(lo, hi);
138.         assert(BitmapView::range_set(lo, hi) =~= vstd::set_lib::set_int_range(lo, hi)) by {
139.             assert forall|i: int|
140.                 BitmapView::range_set(lo, hi).contains(i) == vstd::set_lib::set_int_range(
141.                     lo,
142.                     hi,
143.                 ).contains(i) by {}
144.         }
145.     }
