147.     //==================================================================================================
148.     // Lemmas: Free Range Properties
149.     //==================================================================================================
150. 
151.     /// If a free range of size n exists starting at p, then usage <= number_of_bits - n.
152.     proof fn lemma_free_range_implies_usage_bound(&self, p: int, n: int)
153.         requires
154.             self.wf(),
155.             self.has_free_range_at(p, n),
156.             n > 0,
157.         ensures
158.             self.usage() <= self.num_bits - n,
159.     {
160.         let num_bits: int = self.num_bits;
161.         let full_range: Set<int> = vstd::set_lib::set_int_range(0, num_bits);
162.         vstd::set_lib::lemma_int_range(0, num_bits);
163.         let free_range: Set<int> = vstd::set_lib::set_int_range(p, p + n);
164.         vstd::set_lib::lemma_int_range(p, p + n);
165.         let available_range: Set<int> = full_range.difference(free_range);
166. 
167.         assert(self.set_bits.subset_of(available_range)) by {
168.             assert forall|i: int|
169.                 #![auto]
170.                 self.set_bits.contains(i) implies available_range.contains(i) by {
171.                 if p <= i && i < p + n {
172.                     assert(!self.is_bit_set(i));
173.                 }
174.             }
175.         }
176. 
177.         vstd::set_lib::lemma_set_subset_finite(full_range, available_range);
178.         vstd::set_lib::lemma_len_subset(self.set_bits, available_range);
179. 
180.         assert(free_range.subset_of(full_range)) by {
181.             assert forall|i: int| free_range.contains(i) implies full_range.contains(i) by {}
182.         }
183.         vstd::set_lib::lemma_len_difference(full_range, free_range);
184.         assert(full_range.intersect(free_range) =~= free_range);
185.         assert(full_range =~= available_range.union(free_range));
186.         assert(available_range.intersect(free_range) =~= Set::empty());
187.         vstd::set_lib::lemma_set_disjoint_lens(available_range, free_range);
188.     }
189. 
190.     //==================================================================================================
191.     // Lemmas: Miscellaneous
192.     //==================================================================================================
193. 
194.     /// Lemma: If set_bits ⊆ [0, n) and there's an element x in [0, n) not in set_bits,
195.     /// then |set_bits| < n, so inserting one element still satisfies |set_bits| <= n.
196.     pub proof fn lemma_insert_preserves_usage_bound(&self, x: int)
197.         requires
198.             self.wf(),
199.             0 <= x < self.num_bits,
200.             !self.set_bits.contains(x),
201.         ensures
202.             self.set_bits.insert(x).len() <= self.num_bits,
203.     {
204.         let full_range: Set<int> = vstd::set_lib::set_int_range(0, self.num_bits);
205.         vstd::set_lib::lemma_int_range(0, self.num_bits);
206.         assert(self.set_bits.subset_of(full_range)) by {
207.             assert forall|i: int| #![auto] self.set_bits.contains(i) implies full_range.contains(
208.                 i,
209.             ) by {}
210.         }
211.         self.set_bits.lemma_subset_not_in_lt(full_range, x);
212.     }
213. 
214.     /// If usage equals number_of_bits, all bits are set.
215.     pub proof fn lemma_usage_equals_number_of_bits_implies_full(&self)
216.         requires
217.             self.wf(),
218.             self.usage() == self.num_bits,
219.         ensures
220.             forall|i: int| 0 <= i < self.num_bits ==> self.is_bit_set(i),
221.     {
222.         let full_range: Set<int> = vstd::set_lib::set_int_range(0, self.num_bits);
223.         vstd::set_lib::lemma_int_range(0, self.num_bits);
224.         assert(self.set_bits.subset_of(full_range)) by {
225.             assert forall|i: int| #![auto] self.set_bits.contains(i) implies full_range.contains(
226.                 i,
227.             ) by {}
228.         }
229.         assert forall|i: int| 0 <= i < self.num_bits implies self.set_bits.contains(i) by {
230.             if !self.set_bits.contains(i) {
