234.                         #![auto]
235.                         self.set_bits.contains(j) implies reduced.contains(j) by {}
236.                 }
237.                 vstd::set_lib::lemma_len_subset(self.set_bits, reduced);
238.                 vstd::set_lib::lemma_set_subset_finite(full_range, reduced);
239.             }
240.         }
241.     }
242. 
243.     /// If usage() < number_of_bits(), then the bitmap is not full.
244.     pub proof fn lemma_usage_less_than_capacity_means_not_full(&self)
245.         requires
246.             self.wf(),
247.             self.usage() < self.num_bits,
248.         ensures
249.             !self.is_full(),
250.     {
251.         let full_range: Set<int> = vstd::set_lib::set_int_range(0, self.num_bits);
252.         vstd::set_lib::lemma_int_range(0, self.num_bits);
253.         assert(self.set_bits.subset_of(full_range)) by {
254.             assert forall|i: int| #![auto] self.set_bits.contains(i) implies full_range.contains(
255.                 i,
256.             ) by {}
257.         }
258.         vstd::set_lib::lemma_len_subset(self.set_bits, full_range);
